// HTML → Markdown, the one converter in the pad.
//
// Backed by Turndown (vendor/turndown/turndown.js, generated by
// tools/build-vendor-turndown.mjs). The import is relative on purpose: src/ is
// loaded both bundled (esbuild) and unbundled (standalone index.html, every
// test suite), and only a real relative URL resolves in all of them.
//
// Turndown is never called directly by feature code — it is configured here,
// once, behind two named profiles, so the two call sites cannot drift and
// SharePoint-specific rules live in exactly one place:
//
//   'listField'   — rich-text (Note) column values inside the Lists item
//                   export. Headings flatten to bold lines and tables join
//                   with ' | ' and no separator row, because that document
//                   already owns '##' for its per-item structure and a real
//                   heading inside a field value would forge one.
//   'pageContent' — the body of a text web part in the Pages content export.
//                   The web part's own outline *is* the content, so headings
//                   become real ATX headings demoted to sit under the part's
//                   own '## <label>' heading, and tables become real markdown
//                   tables.
//
// Caller-supplied HTML is expected to be sanitized already (canvas.js
// sanitizeHtml). Turndown is additionally configured to keep no raw HTML and
// to drop the executable/embedded elements outright, so no tag can survive
// into the output for a permissive markdown renderer to act on.

import TurndownService from '../vendor/turndown/turndown.js';

// Dropped whole — content and all. sanitizeHtml already removes most of these
// upstream; repeating them here means the converter is safe on its own terms
// rather than by assumption about its caller.
const DROPPED = ['script', 'style', 'noscript', 'iframe', 'object', 'embed', 'form'];

const BASE_OPTIONS = {
  headingStyle: 'atx',
  hr: '---',
  bulletListMarker: '-',
  codeBlockStyle: 'fenced',
  emDelimiter: '*',
  strongDelimiter: '**',
  linkStyle: 'inlined',
  // Anything Turndown has no rule for contributes its text, never its markup.
  // This is what keeps '<div onclick=…>' from reaching a markdown renderer.
  blankReplacement: (content, node) => (node.isBlock ? '\n\n' : ''),
  keepReplacement: (content) => content,
  defaultReplacement: (content, node) => (node.isBlock ? `\n\n${content}\n\n` : content),
};

// Markdown link targets: parentheses would close the syntax early, and
// SharePoint file names may legitimately contain them.
const encodeTarget = (url) => String(url).replace(/\(/g, '%28').replace(/\)/g, '%29');
const escapeLabel = (label) => String(label).replace(/([[\]])/g, '\\$1');

// A javascript: target is not a link — the text stays, the href does not.
const isSafeHref = (href) => Boolean(href) && !/^\s*javascript:/i.test(href);

// Markdown has no table inside a table cell. A nested one contributes its
// text instead, so the outer table still renders rather than collapsing into
// a row of escaped pipes.
const cellText = (turndown, cell) => {
  const clone = cell.cloneNode(true);
  for (const nested of clone.querySelectorAll('table')) {
    nested.replaceWith(clone.ownerDocument.createTextNode(
      ` ${(nested.textContent || '').replace(/\s+/g, ' ').trim()} `,
    ));
  }
  return turndown.turndown(clone.innerHTML || '').replace(/\s+/g, ' ').trim();
};

// Only this table's own rows: a nested table is its own block, not extra rows.
const ownRows = (table) => [...table.querySelectorAll(
  ':scope > tr, :scope > thead > tr, :scope > tbody > tr, :scope > tfoot > tr',
)];

function addSharedRules(turndown) {
  turndown.remove(DROPPED);

  // Turndown's own list rule pads to '-   item' and indents continuations by
  // four spaces. Valid, but noisy in a document meant to be read and diffed.
  // This emits '- item' / '1. item' and indents continuation lines by exactly
  // the prefix width, which is all CommonMark needs to keep them in the item.
  turndown.addRule('tightListItem', {
    filter: 'li',
    replacement: (content, node, options) => {
      const parent = node.parentNode;
      let prefix = `${options.bulletListMarker} `;
      if (parent.nodeName === 'OL') {
        const start = Number(parent.getAttribute('start'));
        const index = [...parent.children].indexOf(node);
        prefix = `${(Number.isFinite(start) && start ? start : 1) + index}. `;
      }
      const body = content
        .replace(/^\n+/, '')
        .replace(/\n+$/, '\n')
        .replace(/\n/gm, `\n${' '.repeat(prefix.length)}`);
      return prefix + body + (node.nextSibling && !/\n$/.test(body) ? '\n' : '');
    },
  });

  turndown.addRule('safeLink', {
    filter: (node) => node.nodeName === 'A' && node.getAttribute('href'),
    replacement: (content, node) => {
      const href = node.getAttribute('href');
      // `content` has already been through Turndown's escaping — escaping it
      // again would double every backslash. Only a bare href used as the
      // label is raw text that still needs it.
      const label = content.trim() || escapeLabel(href);
      if (!isSafeHref(href)) return label;
      return `[${label}](${encodeTarget(href)})`;
    },
  });

  turndown.addRule('safeImage', {
    filter: 'img',
    replacement: (_content, node) => {
      const src = node.getAttribute('src');
      if (!isSafeHref(src)) return '';
      return `![${escapeLabel(node.getAttribute('alt') || '')}](${encodeTarget(src)})`;
    },
  });

  // Classic SharePoint wraps every rich-text field body in these, and a
  // publishing page nests them several deep. Unwrapping keeps the wrapper
  // from becoming a stray blank block between real paragraphs.
  turndown.addRule('spRichTextWrapper', {
    filter: (node) => node.nodeName === 'DIV'
      && /(^|\s)(ExternalClass[0-9A-F]+|ms-rtestate-(field|read|write))(\s|$)/.test(
        node.getAttribute('class') || '',
      ),
    replacement: (content) => (content.trim() ? `\n\n${content.trim()}\n\n` : ''),
  });
}

// Headings flattened to bold: a heading inside a field value would forge
// structure in a document whose '##' means "next item".
function addBoldHeadings(turndown) {
  turndown.addRule('headingAsBold', {
    filter: ['h1', 'h2', 'h3', 'h4', 'h5', 'h6'],
    replacement: (content) => {
      const core = content.replace(/\s+/g, ' ').trim();
      return core ? `\n\n**${core}**\n\n` : '';
    },
  });
}

// Headings kept, demoted to sit under the part's own '## <label>'. h1 and h2
// both land at `base` — SharePoint's text editor uses them interchangeably for
// a top-level heading, and neither may collide with the part heading above it.
function addDemotedHeadings(turndown, base) {
  turndown.addRule('headingDemoted', {
    filter: ['h1', 'h2', 'h3', 'h4', 'h5', 'h6'],
    replacement: (content, node) => {
      const core = content.replace(/\s+/g, ' ').trim();
      if (!core) return '';
      const level = Number(node.nodeName.charAt(1));
      const depth = Math.min(6, Math.max(base, base + level - 2));
      return `\n\n${'#'.repeat(depth)} ${core}\n\n`;
    },
  });
}

// Rows joined with ' | ' and no separator: readable, deliberately not
// re-parseable as a table.
function addPipeTables(turndown) {
  turndown.addRule('pipeTable', {
    filter: 'table',
    replacement: (_content, node) => {
      const rows = ownRows(node)
        .map((tr) => [...tr.children].map((td) => cellText(turndown, td)).join(' | '));
      return rows.length ? `\n\n${rows.join('\n')}\n\n` : '';
    },
  });
}

// A real markdown table. Markdown has no header-less table, so the first row
// is the header — which is what it already is whenever the author used <th>.
// Ragged rows are padded to the widest, so the table still renders.
function addMarkdownTables(turndown) {
  turndown.addRule('markdownTable', {
    filter: 'table',
    replacement: (_content, node) => {
      const rows = ownRows(node).map((tr) => [...tr.children]
        .map((td) => cellText(turndown, td).replace(/\|/g, '\\|')));
      if (!rows.length) return '';
      const width = Math.max(...rows.map((row) => row.length));
      const line = (cells) => `| ${[
        ...cells, ...Array(Math.max(0, width - cells.length)).fill(''),
      ].join(' | ')} |`;
      const separator = `| ${Array(width).fill('---').join(' | ')} |`;
      return `\n\n${[line(rows[0]), separator, ...rows.slice(1).map(line)].join('\n')}\n\n`;
    },
  });
}

const PROFILES = {
  listField: (turndown) => {
    addSharedRules(turndown);
    addBoldHeadings(turndown);
    addPipeTables(turndown);
  },
  pageContent: (turndown) => {
    addSharedRules(turndown);
    // '## <part label>' sits above every text part, so '###' is the shallowest
    // depth a page heading may take without competing with it.
    addDemotedHeadings(turndown, 3);
    addMarkdownTables(turndown);
  },
};

// Turndown instances are stateless between calls and cost a rule-table build,
// so each profile is constructed once and reused.
const instances = new Map();

function serviceFor(profile) {
  if (!instances.has(profile)) {
    const configure = PROFILES[profile];
    if (!configure) throw new Error(`Unknown html-markdown profile: ${profile}`);
    const turndown = new TurndownService(BASE_OPTIONS);
    configure(turndown);
    instances.set(profile, turndown);
  }
  return instances.get(profile);
}

// The whole API. `profile` names one of PROFILES; anything else throws rather
// than silently converting under the wrong structural conventions.
export function htmlToMarkdown(html, profile = 'listField') {
  const source = String(html ?? '');
  if (!source.trim()) return '';
  return serviceFor(profile)
    .turndown(source)
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

export const HTML_MARKDOWN_PROFILES = Object.keys(PROFILES);
